import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const h=JSON.parse('{"title":"10.2 专利权、商标权与商业秘密 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"10-标准化与知识产权/02-专利商标与商业秘密.md","filePath":"10-标准化与知识产权/02-专利商标与商业秘密.md"}'),g={name:"10-标准化与知识产权/02-专利商标与商业秘密.md"};function d(a,t,e,l,u,i){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_10-2-专利权、商标权与商业秘密-★★" tabindex="-1">10.2 专利权、商标权与商业秘密 ★★ <a class="header-anchor" href="#_10-2-专利权、商标权与商业秘密-★★" aria-label="Permalink to &quot;10.2 专利权、商标权与商业秘密 ★★&quot;">​</a></h1><p><strong>动机</strong>：著作权保护&quot;表达&quot;（代码写法、文档），不保护&quot;思想&quot;（算法思路、技术方案）。一项新技术方案（比如新的压缩算法实现、新的电路结构）想保护&quot;点子本身&quot;，就要走<strong>专利</strong>这条路——用&quot;公开换保护&quot;：把技术方案公开给社会，国家给你一段时期的独占实施权。</p><h3 id="三种专利与保护期-数字必背" tabindex="-1">三种专利与保护期（数字必背） <a class="header-anchor" href="#三种专利与保护期-数字必背" aria-label="Permalink to &quot;三种专利与保护期（数字必背）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>保护对象</th><th>保护期（自<strong>申请日</strong>起算）</th></tr></thead><tbody><tr><td><strong>发明专利</strong></td><td>新的技术方案（方法、产品）</td><td><strong>20 年</strong></td></tr><tr><td><strong>实用新型</strong></td><td>产品的小改进（&quot;小发明&quot;）</td><td><strong>10 年</strong></td></tr><tr><td><strong>外观设计</strong></td><td>产品的富有美感的新外观</td><td><strong>15 年</strong>（2021 年 6 月 1 日新《专利法》施行起；旧资料写 10 年是修法前的旧标准，考试按现行法 15 年）</td></tr></tbody></table><p><strong>口诀</strong>：「发 20、实 10、外 15」——发明最值钱管 20 年，实用新型是&quot;小改良&quot;管 10 年，外观设计修法后加码到 15 年。<strong>起算点统一是申请日</strong>（不是授权日、不是公告日），反例：把外观设计保护期选成&quot;自授权日起 10 年&quot;——两处都错（起算点错、年限错）。</p><h3 id="授权原则与归属" tabindex="-1">授权原则与归属 <a class="header-anchor" href="#授权原则与归属" aria-label="Permalink to &quot;授权原则与归属&quot;">​</a></h3><ul><li><strong>先申请原则</strong>：两个以上申请人分别就<strong>同样的发明创造</strong>申请专利的，专利权授予<strong>最先申请</strong>的人。专利不像著作权&quot;自动产生&quot;，它<strong>先到先得、只授一家</strong>——哪怕你确实独立想出来的，只要晚了一步就拿不到。同一天申请的，由申请人<strong>协商解决</strong>。</li><li><strong>授权三条件</strong>：<strong>新颖性、创造性、实用性</strong>（缺一不可）。</li><li><strong>职务发明</strong>：<strong>执行本单位的任务</strong>或者<strong>主要利用本单位的物质技术条件</strong>所完成的发明创造是职务发明，<strong>申请专利的权利属于单位</strong>；申请被批准后，单位是专利权人。（&quot;业余时间做的&quot;不改变归属——只要属于执行本单位任务或用了单位的设备资料，就是职务发明。）</li><li><strong>不授予专利权的对象</strong>（爱做干扰项）：科学发现；<strong>智力活动的规则和方法</strong>（如算法、游戏规则、管理方法）；<strong>疾病的诊断和治疗方法</strong>；动物和植物品种（但其生产方法可以授予）；原子核变换方法获得的物质。</li></ul><p><strong>应试动作</strong>：背四个数——20/10/15/先申请。认题特征：题干出现&quot;两公司先后申请同一发明&quot;→ 先申请者得；&quot;某人利用公司设备/承担公司课题做出发明&quot;→ 归公司；选项里出现&quot;疾病诊疗方法、智力活动规则&quot;→ 不授予专利。年份类选项注意现行法口径：外观设计 <strong>15 年</strong>。</p><hr><h2 id="第四节-商标权与商业秘密-★" tabindex="-1">第四节 商标权与商业秘密 ★ <a class="header-anchor" href="#第四节-商标权与商业秘密-★" aria-label="Permalink to &quot;第四节 商标权与商业秘密 ★&quot;">​</a></h2><p><strong>动机</strong>：著作权管作品、专利管技术，商标管的是<strong>牌子</strong>——消费者认牌子买东西，法律就要保护牌子上凝聚的商誉，防止别人搭便车、以次充好。</p><h3 id="商标权要点" tabindex="-1">商标权要点 <a class="header-anchor" href="#商标权要点" aria-label="Permalink to &quot;商标权要点&quot;">​</a></h3><ul><li><strong>注册取得</strong>：商标权通过<strong>注册</strong>取得（与著作权的&quot;自动产生&quot;不同！）。经核准注册的商标为注册商标，注册人享有商标专用权。</li><li><strong>有效期 10 年，自核准注册之日起算</strong>；期满需要继续使用的，<strong>期满前 12 个月内</strong>办理续展；来不及的还有 <strong>6 个月宽展期</strong>；<strong>每次续展 10 年，续展次数不限</strong>——牌子经营得好可以无限续命。</li><li><strong>必须使用注册商标的商品</strong>：现行法律法规下只有<strong>烟草制品</strong>（卷烟、雪茄烟、有包装的烟丝必须申请注册，未经核准不得生产销售）。</li><li>商标注册申请同样适用<strong>先申请原则</strong>（相同或近似的商标，先申请者优先）。</li></ul><p><strong>记忆口诀</strong>：「商标 10 年核准起，前 12 后 6 可续展，续满 10 年无限次，烟草强制要注册」。反例演示：把商标有效期起算点写成&quot;使用之日&quot;或&quot;申请之日&quot;——错，商标是<strong>核准注册之日</strong>；对比专利的&quot;申请日&quot;起算，两者不同，对比着背。</p><h3 id="商业秘密" tabindex="-1">商业秘密 <a class="header-anchor" href="#商业秘密" aria-label="Permalink to &quot;商业秘密&quot;">​</a></h3><p>不为公众所知悉、具有商业价值并经权利人<strong>采取相应保密措施</strong>的技术信息、经营信息等商业信息。特点：</p><ul><li><strong>不需要登记、不需要申请</strong>，靠保密措施维持；</li><li><strong>保护期没有固定年限</strong>——保密措施在就受保护，秘密一旦公开（或被他人独立研发/反向工程出来）即失去保护；</li><li>别人<strong>自己独立想出来</strong>或通过反向工程获得同样的秘密，不构成侵权（这与专利的独占性相反：专利公开换独占，哪怕别人独立想到也侵权；商业秘密靠捂着，捂不住就没了）。</li></ul><p><strong>选专利还是选商业秘密？三问定夺</strong>：这是一道常考的场景决策题——技术方案摆在面前，到底申请专利还是当作商业秘密捂着？用三问秒判：</p><ul><li><strong>① 能被逆向出来吗？</strong> 技术一旦上市就逃不过对手拆解（如电路、配方可通过剖析产品得到）→ 只能申请专利（公开换保护）；反之连产品都见不到、只藏在厂房内部（如工艺流程、客户名单）→ 可当商业秘密捂着。</li><li><strong>② 想要独占还是保密？</strong> 专利独占性最强——哪怕别人独立想出来也侵权，但前提是<strong>技术方案必须能公开</strong>；若公开等于把秘密送人，就选商业秘密。</li><li><strong>③ 能保密多久？</strong> 商业秘密保护期不定，&quot;只要守得住就一直有效&quot;；专利有 20/10/15 年的倒计时，到期技术公开进入公有领域。</li></ul><p>考题识别特征：题干出现&quot;某配方向来密不示人、未申请任何知识产权、靠保密措施维持&quot;→ 商业秘密；出现&quot;虽独立研发，但因先被别人申请了专利而无权实施&quot;→ 专利场景。</p><h3 id="四权对比总表-一张表背完四大权利" tabindex="-1">四权对比总表（一张表背完四大权利） <a class="header-anchor" href="#四权对比总表-一张表背完四大权利" aria-label="Permalink to &quot;四权对比总表（一张表背完四大权利）&quot;">​</a></h3><p>把选择题最爱混的四样东西并排对比，凡是&quot;取得方式 / 保护期 / 能否独立研发&quot;类的题，直接查这一行：</p><table tabindex="0"><thead><tr><th>维度</th><th>著作权</th><th>专利权</th><th>商标权</th><th>商业秘密</th></tr></thead><tbody><tr><td>取得方式</td><td><strong>自动产生</strong>（创作完成即享有）</td><td><strong>申请 + 授权</strong>（先申请者得）</td><td><strong>注册取得</strong>（核准注册）</td><td><strong>靠保密措施</strong>（不登记不申请）</td></tr><tr><td>保护对象</td><td>作品的<strong>表达</strong>（代码、文档）</td><td>技术<strong>方案/外观</strong>（方法、产品、造型）</td><td><strong>品牌标识</strong>（文字、图形、组合）</td><td>未公开的<strong>技术/经营信息</strong></td></tr><tr><td>保护期</td><td>自然人生前+死后 50 年；法人按规定</td><td><strong>20/10/15 年</strong>（自申请日）</td><td><strong>10 年</strong>，可无限续展</td><td><strong>无固定年限</strong>，靠保密维持</td></tr><tr><td>是否需申请</td><td>否</td><td>是</td><td>是</td><td>否</td></tr><tr><td>别人独立研发/独立想出</td><td><strong>可能侵权</strong>（只要表达相同即抄）</td><td><strong>侵权</strong>（先申请独占，独立想到也侵权）</td><td><strong>侵权</strong>（易混淆近似标识不得注册）</td><td><strong>不侵权</strong>（独立研发/反向工程合法）</td></tr></tbody></table><p><strong>应试动作</strong>：背两组对比——①著作权自动产生 vs 商标注册取得 vs 商业秘密靠保密措施；②专利&quot;独立想到也侵权&quot; vs 商业秘密&quot;独立想到不侵权&quot;。认题特征：题干说&quot;某企业技术配方一直保密、未申请专利&quot;→ 商业秘密，保护期不定、他人独立研发不侵权；再看一眼总表第五行就能对上&quot;独立研发是否侵权&quot;。此考点无计算，纯对照。</p><hr>',25)])])}const _=o(g,[["render",d]]);export{h as __pageData,_ as default};
